      doc.moveDown()
      doc.moveDown()
      doc.font('Times-Roman').fontSize(15).text(req.__('Thank you for your order!'))

      challengeUtils.solveIf(challenges.negativeOrderChallenge, () => { return totalPrice < 0 })

      if (req.body.UserId) {
