      }

      db.ordersCollection.insert({
        promotionalAmount: discountAmount,
        paymentId: req.body.orderDetails ? req.body.orderDetails.paymentId : null,
        addressId: req.body.orderDetails ? req.body.orderDetails.addressId : null,
