        products: basketProducts,
        bonus: totalPoints,
        deliveryPrice: deliveryAmount,
        eta: deliveryMethod.eta.toString()
      }).then(() => {
        doc.end()
      })
    } else {
      next(new Error(`Basket with id=${id} does not exist.`))
    }
